mapper.select:
SELECT id, created_at
FROM booking_order
WHERE order_no = #{orderNo}
  AND user_id = #{userId}

SELECT b.order_no, b.resource_id, b.book_date, b.start_slot, b.end_slot, b.purpose, b.status, b.source, b.charged_slots, b.start_at, b.end_at, b.check_in_open_at, b.check_in_deadline, b.checked_in_at, b.terminated_at, b.termination_reason, b.reason_text, b.version, b.created_at, b.updated_at, r.name AS resource_name, r.location AS resource_location, j.job_no AS release_job_no, j.status AS release_status FROM booking_order b JOIN resource r ON r.id = b.resource_id LEFT JOIN release_job j ON j.source_booking_id = b.id WHERE b.user_id = #{userId}
AND (b.created_at < #{anchor.createdAt} OR (b.created_at = #{anchor.createdAt} AND b.id < #{anchor.id}))
ORDER BY b.created_at DESC, b.id DESC LIMIT #{fetchSize}
